(function () {
  'use strict';
  window.WBEnrich = function (ctx) {
    const {D,M,esc:e,icon,badge,heading,link,modal,toast}=ctx;
    let L=window.WBLibrary||{projects:[],works:[],ideas:[],skills:[],knowledge:[],counts:{},coverage:{}};
    let news={items:[],sources:[],updatedAt:null},connected=false,busy=false,projectCategory='全部',knowledgeTab='方法与案例',libraryQuery='',radarTab='最新资讯',contentTab='作品与素材',queue=Promise.resolve();
    const date=v=>{try{return new Intl.DateTimeFormat('zh-CN',{timeZone:'America/Los_Angeles',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v));}catch{return v||'未记录';}};
    const tabs=(values,current,action)=>`<div class="tab-bar">${values.map(v=>`<button data-action="${action}" data-value="${e(v)}" aria-pressed="${current===v}" class="${current===v?'active':''}">${e(v)}</button>`).join('')}</div>`;
    const empty=(title,body)=>`<div class="empty-inline">${icon('book-open')}<div><strong>${e(title)}</strong><p>${e(body)}</p></div></div>`;
    const categoryIcon=c=>/网站|业务|独立站/.test(c)?'globe':/视频|作品/.test(c)?'clapperboard':/知识/.test(c)?'book-open':'target';
    const collectionStats=()=>`<div class="collection-stats">${[['projects','项目','projects'],['works','作品家族','content'],['skills','Skill 说明','knowledge'],['knowledge','知识入口','knowledge'],['ideas','思路与计划','board']].map(([k,t,r])=>`<a href="#${r}" data-action="stat-link" data-route="${r}" data-kind="${k}"><strong>${connected?(L[k]?.length||0):'…'}</strong><span>${t}</span>${icon('arrow-up-right')}</a>`).join('')}</div>`;
    async function api(url,options){const res=await fetch(url,options);const data=await res.json();if(!res.ok)throw Error(data.error||'本机服务暂时不可用');return data;}
    function applyCatalog(){
      D.tasks=[];
      D.projects=L.projects.map(p=>({id:p.id,title:p.title,category:p.category,icon:categoryIcon(p.category),stage:p.status,steps:null,current:0,desc:p.summary,next:p.next,evidence:(p.evidence||[]).map(x=>x.note||'来源记录').join('；'),route:p.id==='packrivo'?'business':/video|film|series/.test(p.id)?'content':'projects'}));
    }
    applyCatalog();
    function refsHTML(refs){return `<div class="evidence-list">${(refs||[]).map(r=>`<div><div><strong>${e((r.path||'').split(/[\\/]/).pop()||r.note||'来源')}</strong><small>${e(r.note||'本机原始资料')}${r.line?' · 第 '+r.line+' 行':''}</small>${r.excerpt?`<blockquote>${e(r.excerpt)}</blockquote>`:''}<code>${e(r.path||'')}</code></div>${r.fileId?`<button class="small-button" data-action="source" data-id="${r.fileId}">查看原文</button>`:badge(r.exists?'路径已核对':'路径待核对',r.exists?'teal':'amber')}</div>`).join('')}</div>`;}
    function realProject(p){return `<button class="real-project-card" data-action="real-project" data-id="${e(p.id)}"><div class="real-card-top"><span class="project-icon">${icon(categoryIcon(p.category))}</span><span class="asset-category">${e(p.category)}</span>${icon('arrow-up-right')}</div><h3>${e(p.title)}</h3><p>${e(p.summary)}</p><div class="real-status">${icon('info')}<span>${e(p.status)}</span></div><div class="next-step"><small>下一步</small><span>${e(p.next)}</span></div><span class="record-foot">${(p.evidence||[]).length} 个来源 · ${date(p.sourceUpdatedAt||L.updatedAt)}</span></button>`;}
    function projectMini(p){return `<button class="project-row real-mini" data-action="real-project" data-id="${e(p.id)}"><span class="project-icon">${icon(categoryIcon(p.category))}</span><span class="project-info"><span class="project-name">${e(p.title)}</span><span class="project-next">${e(p.next)}</span><span class="mini-status">${e(p.status)}</span></span>${icon('chevron-right')}</button>`;}
    function newsCard(n,compact=false){const stale=news.sources.find(s=>s.id===n.sourceId)?.status==='error';return `<article class="news-item ${compact?'compact-news':''}"><div class="news-meta">${badge(n.category||'公开资讯','blue')}${stale?badge('上次缓存','amber'):''}<span>${e(n.source)} · ${date(n.publishedAt||n.fetchedAt)}</span></div><a href="${e(n.url)}" target="_blank" rel="noopener noreferrer" class="news-title">${e(n.title)}${icon('arrow-up-right')}</a>${!compact&&n.summary?`<p>${e(n.summary)}</p>`:''}<div class="relevance">${icon('compass')}<span>${e(n.relevance||'建议结合当前项目判断是否值得尝试。')}</span></div>${!compact?`<div class="news-actions"><span>抓取 ${date(n.fetchedAt)} · 官方来源</span><button class="small-button" data-action="news-task" data-id="${e(n.id)}">加入阅读清单</button></div>`:''}</article>`;}
    function topNews(){const candidates=[...news.items].sort((a,b)=>{const score=n=>(/agent|tool|workflow|search|merchant|commerce|模型|智能体/i.test(n.title)?4:0)-(/partnership|funding|earnings|^stable$|^n8n@/i.test(n.title)?3:0)-(/legal|law|medical|healthcare/i.test(n.title)?8:0);return score(b)-score(a);});const selected=[],seen=new Set();for(const n of candidates){if(!seen.has(n.category)){selected.push(n);seen.add(n.category);}if(selected.length===3)break;}return selected;}
    function home(){const tasks=ctx.allTasks(),done=tasks.filter(t=>ctx.getState().done[t.id]).length;const picks=['social-content','personal-workbench','packrivo'].map(id=>L.projects.find(p=>p.id===id)).filter(Boolean);return `<div class="real-intake-bar"><span>${icon('lock-keyhole')} ${connected?'已整理本机资料，原文件保持原位':'正在连接本机资料…'}</span><button class="text-button" data-action="coverage">查看来源与覆盖范围 ${icon('info')}</button></div>${collectionStats()}<div class="home-grid real-home"><div class="home-primary"><section class="panel">${heading('今天要做的事',tasks.length?`已完成 ${done} / ${tasks.length} 项 · 计划 ${tasks.reduce((n,t)=>n+t.minutes,0)} 分钟`:'每天约 1 小时，先挑一件重要的事。',`<button class="small-button" data-action="new-task">${icon('plus')}添加任务</button>`)}${tasks.length?`<div class="tasks">${ctx.tasksHTML()}</div>`:`<div class="today-empty">${icon('list-checks')}<strong>今天的安排，由你来定。</strong><p>从项目的下一步或工具尝试中挑一件，加入今天。</p><button class="primary-button" data-action="project-suggestion">从我的项目找下一步</button></div>`}</section><section class="panel">${heading('项目正在向哪里走','查看真实记录，再决定下一步。',link('projects','全部项目'))}${picks.map(projectMini).join('')}</section></div><section class="real-recommendations">${heading('对你有用的新消息',news.updatedAt?'上次尝试更新 '+date(news.updatedAt):'公开来源，点击后可手动更新。',`<button class="text-button" data-action="news-refresh" ${busy?'disabled':''}>${busy?'更新中…':'刷新资讯'} ${icon('radar')}</button>`)}${topNews().map(n=>newsCard(n,true)).join('')||empty('还没有获取到资讯','点击刷新，读取已选的官方公开来源。')}<div class="section-space">${heading('值得尝试的工具','先做一个小任务，再判断是否适合你。',link('radar','工具雷达'))}${D.tools.slice(0,2).map(t=>`<button class="tool-slim" data-action="tool" data-id="${t.id}"><span class="tool-mark ${t.tone}">${t.monogram}</span><span><strong>${t.name}</strong><small>${e(t.benefit)}</small></span>${icon('chevron-right')}</button>`).join('')}</div></section></div><section class="section-space">${heading('最近的真实作品','成片、课件与演示按作品家族整理；不等同于已发布。',link('content','查看全部'))}<div class="works-grid home-works">${L.works.slice(0,3).map(workCard).join('')}</div></section>${(L.distillations||[]).length?`<section class="distill-home-link">${icon('book-open')}<div><strong>从经验中整理出 ${(L.distillations||[]).length} 张方法与案例卡</strong><p>输入、步骤、检查和边界都留清楚，先选一张有用的。</p></div><button class="small-button" data-action="distill-open">去看看</button></section>`:''}`;}
    function projects(){const cats=['全部',...new Set(L.projects.map(p=>p.category))];return `<section class="goal-banner"><span class="goal-symbol">${icon('target')}</span><div><span>方向已确认 · 计划持续校准</span><h2>用真实实践，积累有用的 AI 干货。</h2><p>外贸、独立站和工作效率都是应用场景。把“输出促进学习”的新记录与当前主线连接起来。</p></div></section>${tabs(cats,projectCategory,'project-category')}<div class="real-projects">${L.projects.filter(p=>projectCategory==='全部'||p.category===projectCategory).map(realProject).join('')}</div><section class="section-space">${heading('项目 → 案例 → 内容 → 能力积累','同一份实践可以连接多个板块，进度只保留一个主记录。')}<div class="workflow">${D.workflows.map((s,i)=>`<div><span>${i+1}</span><strong>${s}</strong></div>`).join('')}</div></section>`;}
    const matching=(r,q)=>!q||[r.title,r.name,r.summary,r.category,...(r.tags||[])].join(' ').toLowerCase().includes(q.toLowerCase());
    function assetList(items,kind){return `<div class="asset-list">${items.map(r=>`<button class="asset-record" data-action="library-record" data-kind="${kind}" data-id="${e(r.id)}"><span class="module-icon">${icon(kind==='skills'?'compass':'book-open')}</span><span class="asset-record-body"><strong>${e(r.title||r.name)}</strong>${r.name?`<small class="skill-name">${e(r.name)}</small>`:''}<p>${e(r.summary)}</p><span class="asset-status">${e(r.category)} · ${e(r.status||'入口已核对')}</span></span>${icon('chevron-right')}</button>`).join('')}</div>`;}
    function knowledge(){const values=['方法与案例','精选 Skill','全部 Skill','知识入口','我的工具体验'];const items=knowledgeTab==='知识入口'?L.knowledge:knowledgeTab==='精选 Skill'?L.skills.filter(s=>s.featured):L.skills;const filtered=items.filter(s=>matching(s,libraryQuery));return `<section class="knowledge-banner">${icon('book-open')}<div><h2>把已经有的积累，用起来。</h2><p>${(L.distillations||[]).length} 张方法与案例卡，${L.skills.length} 份可读 Skill 说明，${L.knowledge.length} 个知识入口。Obsidian 继续保存知识正文。</p></div></section>${tabs(values,knowledgeTab,'knowledge-tab')}${knowledgeTab==='方法与案例'?distillUI.render():knowledgeTab==='我的工具体验'?ctx.trialList():`<div class="library-toolbar"><label class="inline-search">${icon('search')}<input id="library-search" type="search" value="${e(libraryQuery)}" placeholder="按用途、名称或分类查找" aria-label="搜索 Skill 与知识"></label><span id="library-count">${filtered.length} 条结果</span></div><div id="library-results">${filtered.length?assetList(filtered,knowledgeTab==='知识入口'?'knowledge':'skills'):empty('暂时没有匹配项','可以试试“外贸”“视频”“SEO”或“知识”。')}</div>`}<p class="quiet-note">${icon('info')}核对来源与说明，不把目录可读、历史报告或一次通过当成当前业务效果。</p>`;}
    function workCard(w){return `<button class="work-card" data-action="asset" data-id="${e(w.id)}"><span class="work-cover">${w.thumbnailUrl?`<img src="${e(w.thumbnailUrl)}" alt="${e(w.title)}的实际画面" loading="lazy">`:`<span class="work-placeholder">${icon(w.kind==='video'?'clapperboard':'file-text')}<span>${e(w.kind==='video'?'视频原件':'课件与文档')}</span></span>`}<span class="work-type">${w.kind==='video'?'视频':w.kind==='pdf'?'PDF':'课件'}</span></span><span class="work-info"><strong>${e(w.title)}</strong><small>${e(w.summary)}</small><span>${e(w.status)}</span></span></button>`;}
    function content(){const p=ctx.getPlatform();const values=['作品与素材','IP 主线与选题'];return `${tabs(['共用内容库','小红书','抖音','视频号'],p,'real-platform')}${p==='共用内容库'?`${tabs(values,contentTab,'content-tab')}${contentTab==='作品与素材'?`<div class="collection-heading"><div><h2>${L.works.length} 个真实作品家族</h2><p>合并同作品的横版、竖版、成片与手机预览；点击查看原件和版本关系。</p></div>${badge('发布与效果分别核实','amber')}</div><div class="works-grid">${L.works.map(workCard).join('')}</div>`:ipContent()}`:`<section class="platform-intro"><span class="platform-symbol ${p==='小红书'?'red':p==='视频号'?'amber':'navy'}">${p.slice(0,1)}</span><div><h2>${p}内容区</h2><p>从已有作品选素材，分别准备标题、封面、内容版本与发布记录。</p></div>${badge('尚未连接账号')}</section><section class="panel">${heading('可关联的真实素材','这些是已有文件，不代表已在该平台发布。')}<div class="works-grid">${L.works.slice(0,6).map(workCard).join('')}</div></section><div class="section-space">${ipContent()}</div>`}`;}
    function ipContent(){const p=L.projects.find(x=>x.id==='social-content');return `<section class="panel"><div class="section-heading"><div><h2>从“我做过”，到“别人能照着做”</h2><p>内容体系建议：问题、操作、验收、限制与下一步。</p></div><button class="small-button" data-action="local-ideas">从我的资料找思路</button></div><div class="ip-columns"><div><h3>我的主张</h3><p>分享有实操密度的 AI 干货，用输出倒逼学习。</p></div><div><h3>三个应用方向</h3><p>外贸运营、独立站建站、日常工作与创作。</p></div><div><h3>证据与作品</h3><p>真实工程、操作过程和检查方法，形成可以复用的案例。</p></div></div>${p?`<div class="ip-source"><span>依据：较新的内容项目记录；具体系列和选题仍待选择。</span><button class="text-button" data-action="real-project" data-id="${p.id}">查看依据 ${icon('arrow-up-right')}</button></div>`:''}</section><section class="section-space">${heading('已有思路，可以延伸成什么？','只作为候选，不自动占用你的时间。')}<div class="idea-cards">${L.ideas.filter(i=>i.state!=='paused').map(ideaCard).join('')}</div></section>`;}
    function ideaCard(i){const label={confirmed:'已有明确要求',candidate:'待探索',paused:'已退出 / 暂缓'}[i.state]||'我的想法';return `<article class="idea-real"><div>${badge(label,i.state==='paused'?'amber':i.state==='confirmed'?'teal':'blue')}</div><h3>${e(i.title)}</h3><p>${e(i.body)}</p><div class="idea-actions"><button class="text-button" data-action="idea-source" data-id="${e(i.id)}">查看来源 ${icon('file-text')}</button>${i.state!=='paused'?`<button class="small-button" data-action="idea-task" data-id="${e(i.id)}">转成一个小行动</button>`:''}</div></article>`;}
    function board(){return `<div class="board-toolbar"><p>历史想法有来源，新想法随手记；明确以后再转成行动。</p><button class="primary-button" data-action="new-idea">${icon('plus')}新增想法</button></div><div class="idea-cards">${L.ideas.map(ideaCard).join('')}${ctx.getState().ideas.map((i,n)=>`<article class="idea-real user-idea">${badge(i.lane||'我的想法','teal')}<h3>${e(i.title)}</h3><p>${e(i.body)}</p><span class="record-foot">我的本地记录</span></article>`).join('')}</div>`;}
    function business(){const p=L.projects.find(x=>x.id==='packrivo');return `${p?`<section class="panel">${heading('Packrivo：先看最新来源','本地交接报告与当前线上验收，分别记录。')}${projectMini(p)}<p class="quiet-note">${icon('info')}本地报告称已上线，文内后续还记录模板遗漏；发现日期未注明、是否关闭待原项目核对，本轮未复验生产。</p></section>`:''}<section class="section-space">${heading('已有业务项目与能力','从原项目进入，避免复制维护第二套业务数据。')}<div class="real-projects">${L.projects.filter(p=>/业务|工具/.test(p.category)).map(realProject).join('')}</div></section><section class="section-space">${heading('外贸与独立站的知识入口','真实主知识页可直接在本机预览。')}${assetList(L.knowledge.filter(k=>/外贸|运营|独立站|产品|客户|SEO|社媒|询盘/.test(k.title+' '+k.category)).slice(0,12),'knowledge')}</section>`;}
    function sourceStatus(){return `<div class="source-status-list">${news.sources.map(s=>`<div><span><strong>${e(s.name)}</strong><small>${e(s.category)} · ${s.status==='ok'?s.count+' 条':s.status==='error'?'本次获取失败':'尚未获取'}</small>${s.error?`<p>${e(s.error)}</p>`:''}${s.retainedCount?`<small>保留 ${s.retainedCount} 条旧记录 · 上次成功 ${date(s.lastSuccessAt)}</small>`:''}</span>${badge(s.status==='ok'?'本次已更新':s.status==='error'?(s.retainedCount?'保留旧记录':'本次未获取'):'待更新',s.status==='ok'?'teal':'amber')}</div>`).join('')}</div>`;}
    function radar(){return `<div class="radar-intro">${icon('radar')}<p><strong>新消息，连接到你的下一步。</strong><span>公开来源手动更新；原文、日期和推荐理由分开显示。</span></p><button class="primary-button" data-action="news-refresh" ${busy?'disabled':''}>${icon('radar')}${busy?'正在获取…':'刷新公开资讯'}</button></div>${tabs(['最新资讯','工具雷达','IP 与内容思路','信息源状态'],radarTab,'real-radar-tab')}${news.updatedAt?`<p class="update-caption">最近抓取尝试：${date(news.updatedAt)} · ${news.sources.filter(s=>s.status==='ok').length} / ${news.sources.length} 个源成功；失败源保留原抓取日期。</p>`:''}${radarTab==='最新资讯'?`<div class="live-news-grid">${news.items.map(n=>newsCard(n)).join('')||empty('点击刷新，读取公开信息','无需API Key；原始标题可能是英文，AI翻译与解释留待后续接入。')}</div>`:radarTab==='工具雷达'?`<div class="tools-grid">${D.tools.slice(0,2).map(t=>ctx.toolHTML(t,true)).join('')}</div><section class="section-space">${heading('AI 工具的新发布','来自官方发布源；发布记录不等于已实测。')}<div class="live-news-grid">${news.items.filter(n=>/AI|工具|自动化/.test(n.category)).map(n=>newsCard(n)).join('')}</div></section>`:radarTab==='IP 与内容思路'?ipContent():sourceStatus()}<p class="quiet-note">${icon('info')}当前更新通过公开RSS/Atom获取，推荐理由来自来源类别与本地规则，没有调用付费AI API。${link('connections','查看 AI 接入规划')}</p>`;}
    const aiUses=[['资讯理解助手','将已获取的公开资料翻译、归纳并附来源；判断与你的工作有什么关系。','公开资讯正文'],['IP 与选题助手','结合经你选择的定位、案例摘要，提出内容系列、选题和表达角度。','公开资料＋经确认的摘要'],['项目推进助手','基于你选定的进度摘要，找缺口、拆下一步、帮助做取舍。','需你确认的项目摘要'],['工具试用助手','把工具能力转成小任务、检查清单与试用复盘。','公开工具资料'],['知识与作品关联','推荐已有知识和作品之间的联系；正文仍由Obsidian维护。','先本地检索，按需确认外传'],['复盘助手','根据你选定的记录，提炼继续、停止和调整建议。','私人记录，另行确认']];
    function connections(){return aiUI.view();}
    function openRecord(kind,id){const r=(L[kind]||[]).find(x=>x.id===id);if(!r)return;modal(r.title||r.name,`<p class="dialog-lead">${e(r.summary)}</p>${badge(r.category,'blue')}${badge(r.status||'入口已核对')}<div class="detail-block">${r.name?`<h3>Skill 名称</h3><p>${e(r.name)}</p>`:''}<h3>入口与证据</h3><p>${e(r.evidence||'根据当前可读文件整理；不修改原知识库。')}</p><code class="local-path">${e(r.path)}</code><small class="source-date">当前核对 ${date(r.observedAt||L.updatedAt)}</small></div><div class="dialog-actions"><button class="outline-button" data-action="copy-path" data-path="${e(r.path)}">复制路径</button>${r.fileId?`<button class="primary-button" data-action="source" data-id="${r.fileId}">预览原文</button>`:''}</div>`,'我的真实资料');}
    function openProject(id){const p=L.projects.find(x=>x.id===id);if(!p)return;modal(p.title,`${badge(p.category,'blue')}<p class="dialog-lead">${e(p.summary)}</p><div class="detail-block"><h3>当前记录</h3><p>${e(p.status)}</p><h3>下一步</h3><p>${e(p.next)}</p>${p.workflowSteps?`<h3>项目流程</h3><p>${p.workflowSteps.map(e).join(' → ')}</p>`:''}<h3>来源与完成证据</h3>${refsHTML(p.evidence)}<p class="quiet-note">${e(p.certainty||'原始报告与本轮实际验证范围分别记录。')}</p></div><div class="dialog-actions"><button class="primary-button" data-action="project-task" data-id="${e(p.id)}">把下一步加入今天</button></div>`,'真实项目与来源');}
    function addTask(title,bodyText,minutes=20,details={}){const t=M.addTask(ctx.getState(),title,minutes);if(!t)return;t.body=bodyText||title;t.evidence=details.evidence||'完成一个可检查的小结果，并在备注或复盘中留下依据。';if(details.sourceCardId)t.sourceCardId=details.sourceCardId;ctx.save();toast('已加入今日任务，建议先检查总时长');if(document.querySelector('#dialog').open)document.querySelector('#dialog').close();ctx.render();}
    async function openSource(id){modal('正在读取本机原文…','<p class="dialog-lead">原件只读，内容不会发送到外部服务。</p>','资料来源');try{const r=await api('/api/source/'+id);document.querySelector('#dialog-content').innerHTML=`<h2 id="dialog-title">本机原文预览</h2><code class="local-path">${e(r.path)}</code><p class="source-date">原文件修改 ${date(r.modifiedAt)}${r.truncated?' · 仅展示前256KB':''}</p><pre class="source-preview">${e(r.text)}</pre>`;}catch(err){document.querySelector('#dialog-content').innerHTML=`<h2 id="dialog-title">暂时无法读取</h2><p class="dialog-lead">${e(err.message)}</p><p>请用本地网址打开工作台，并确认原文件仍在原位。</p>`;}}
    function openAsset(id){const w=L.works.find(x=>x.id===id);if(!w)return;const media=w.fileId?(w.kind==='video'?`<video class="asset-video" controls preload="metadata" ${w.thumbnailUrl?`poster="${e(w.thumbnailUrl)}"`:''} src="/api/asset/${w.fileId}"></video>`:/\.(png|jpe?g|webp|gif)$/i.test(w.path)?`<img class="asset-image" src="/api/asset/${w.fileId}" alt="${e(w.title)}">`:`<a class="outline-button" href="/api/asset/${w.fileId}" target="_blank" rel="noopener">打开文档原件 ${icon('external-link')}</a>`):'<p class="quiet-note">此格式暂不在页面内预览，原件位置已保留，可复制路径后在对应软件打开。</p>';modal(w.title,`${media}<p class="dialog-lead">${e(w.summary)}</p>${badge(w.status,'amber')}<div class="detail-block"><h3>原件位置</h3><code class="local-path">${e(w.path)}</code><button class="text-button" data-action="copy-path" data-path="${e(w.path)}">复制路径</button><h3>相关版本</h3>${refsHTML(w.relatedPaths)}<p class="quiet-note">${e(w.certainty||'文件存在不代表已经发布、公开权或业务效果得到验证。')}</p></div>`,'作品与素材原件');}
    function showCoverage(){const pc=L.coverage.projects||{},kc=L.coverage.knowledge||{};modal('这些资料，整理到了哪里？',`<p class="dialog-lead">复用既有索引，补查新增记录与真实文件；没有把标题扫描说成逐句审阅全部聊天。</p>${collectionStats()}<div class="detail-block"><h3>项目、作品与想法</h3><p>${e(pc.scope||'本机高价值项目与作品资料整理。')}</p><p>Codex 当前标题索引 ${pc.codexIndex?.lines||pc.codexIndex?.rows||'已检查'}；Claude 本机元数据与相关原话按本次范围核对。详细覆盖记录保存在本项目私有资料目录。</p><h3>Skill 与知识</h3><p>${kc.skillDirectoriesReadable||L.skills.length} 份可读说明，精选 ${L.skills.filter(s=>s.featured).length} 个入口；${e(kc.method||'按真实路径去重，只读核对。')}</p><h3>没有推断的事情</h3><p>发布状态、商业效果、真实账号可用性、未读取的附件和其他设备聊天，保持未知或按来源日期说明。</p></div>`,'来源与覆盖范围');}
    async function refreshNews(){if(busy)return;busy=true;ctx.render();try{news=await api('/api/news/refresh',{method:'POST'});toast(`已获取 ${news.items.length} 条公开信息；${news.sources.filter(s=>s.status==='error').length} 个源未成功`);}catch(err){toast('更新失败：'+err.message);}finally{busy=false;ctx.render();}}
    function handleClick(action,el){if(aiUI.handleClick(el))return true;const id=el.dataset.id;if(distillUI.handle(action,el))return true;
      if(action==='stat-link'){if(document.querySelector('#dialog').open)document.querySelector('#dialog').close();if(el.dataset.kind==='knowledge')knowledgeTab='知识入口';if(el.dataset.kind==='skills')knowledgeTab='精选 Skill';ctx.go(el.dataset.route);return true;}
      if(action==='real-project'){openProject(id);return true;}
      if(action==='project'&&L.projects.some(p=>p.id===id)){openProject(id);return true;}
      if(action==='source'){if(document.querySelector('#dialog').open)document.querySelector('#dialog').close();openSource(id);return true;}
      if(action==='asset'){openAsset(id);return true;}
      if(action==='library-record'){openRecord(el.dataset.kind,id);return true;}
      if(action==='project-category'){projectCategory=el.dataset.value;ctx.render();return true;}
      if(action==='knowledge-tab'){knowledgeTab=el.dataset.value;libraryQuery='';ctx.render();return true;}
      if(action==='content-tab'){contentTab=el.dataset.value;ctx.render();return true;}
      if(action==='real-platform'){ctx.setPlatform(el.dataset.value);ctx.render();return true;}
      if(action==='real-radar-tab'){radarTab=el.dataset.value;ctx.render();return true;}
      if(action==='news-refresh'){refreshNews();return true;}
      if(action==='coverage'){showCoverage();return true;}
      if(action==='project-task'){const p=L.projects.find(x=>x.id===id);if(p)addTask(p.next,'来源项目：'+p.title+'。'+p.summary);return true;}
      if(action==='project-suggestion'||action==='local-ideas'){const p=L.projects.find(x=>x.id==='social-content')||L.projects[0];modal('从已有积累，挑一个下一步',`<p class="dialog-lead">基于现有资料的本地建议，没有调用 AI API。</p><div class="detail-block"><h3>${e(p?.title||'从一个真实案例开始')}</h3><p>${e(p?.next||'选一个有过程、有证据的案例，做成一个可照着实践的知识单元。')}</p><h3>也可以从这些思路开始</h3>${L.ideas.filter(i=>i.state==='confirmed'||i.state==='candidate').slice(0,3).map(i=>`<button class="suggestion-button" data-action="idea-task" data-id="${i.id}">${e(i.title)} ${icon('plus')}</button>`).join('')}</div>${p?`<div class="dialog-actions"><button class="primary-button" data-action="project-task" data-id="${p.id}">加入这个项目的下一步</button></div>`:''}`,'可选择的行动建议');return true;}
      if(action==='idea-source'){const i=L.ideas.find(x=>x.id===id);if(i)modal(i.title,`<p class="dialog-lead">${e(i.body)}</p>${refsHTML(i.evidence)}`,'想法的原始依据');return true;}
      if(action==='idea-task'){const i=L.ideas.find(x=>x.id===id);if(i)addTask('推进：'+i.title,i.body);return true;}
      if(action==='news-task'){const n=news.items.find(x=>x.id===id);if(n)addTask('阅读：'+n.title,n.url+'\n'+(n.relevance||''));return true;}
      if(action==='copy-path'){navigator.clipboard.writeText(el.dataset.path).then(()=>toast('路径已复制')).catch(()=>toast('复制未成功，可以在原件位置选中文字复制'));return true;}
      if(action==='recheck-library'){api('/api/library/refresh',{method:'POST'}).then(v=>{L=v;applyCatalog();ctx.render();toast('已重新核对本地入口；未扫描全部聊天');}).catch(err=>toast(err.message));return true;}
      if(action==='backup-state'){persist(ctx.getState()).then(()=>api('/api/state/backup',{method:'POST'})).then(r=>modal('本地记录已备份',`<p class="dialog-lead">任务、备注、想法和复盘已保存到这个文件。</p><code class="local-path">${e(r.path)}</code>`,'本地备份')).catch(err=>toast('备份失败：'+err.message));return true;}
      return false;
    }
    function handleSubmit(form){if(aiUI.handleSubmit(form))return true;if(form.id!=='connection-form')return false;const f=new FormData(form);const baseUrl=String(f.get('baseUrl')||'').trim();if(baseUrl){try{const u=new URL(baseUrl);if(u.username||u.password||u.search||u.hash)throw Error();if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname)))throw Error();}catch{toast('请使用HTTPS地址，或本机HTTP服务地址');return true;}}ctx.getState().connection={provider:String(f.get('provider')||'compatible'),baseUrl,model:String(f.get('model')||'').trim()};ctx.save();toast('连接草稿已保存，尚未调用API');return true;}
    function handleInput(input){aiUI.handleInput(input);if(input.id!=='library-search')return;libraryQuery=input.value;const items=knowledgeTab==='知识入口'?L.knowledge:knowledgeTab==='精选 Skill'?L.skills.filter(s=>s.featured):L.skills;const filtered=items.filter(s=>matching(s,libraryQuery));document.querySelector('#library-count').textContent=filtered.length+' 条结果';document.querySelector('#library-results').innerHTML=filtered.length?assetList(filtered,knowledgeTab==='知识入口'?'knowledge':'skills'):empty('暂时没有匹配项','换个关键词试试。');}
    function extendSearch(q){return [...distillUI.search(q),...L.works.map(w=>({title:w.title,desc:w.summary,action:'asset',id:w.id,icon:'clapperboard'})),...L.skills.filter(s=>s.featured).map(s=>({title:s.title||s.name,desc:s.name+' '+s.summary,action:'library-record',id:s.id,kind:'skills',icon:'compass'})),...L.knowledge.map(k=>({title:k.title,desc:k.summary,action:'library-record',id:k.id,kind:'knowledge',icon:'book-open'}))].filter(r=>!q||(r.title+r.desc).toLowerCase().includes(q));}
    function persist(value){if(!connected)return Promise.resolve();const snapshot=JSON.stringify(value);queue=queue.catch(()=>{}).then(()=>api('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:snapshot})).then(()=>{document.querySelector('#save-state').textContent='已保存到本机文件';}).catch(err=>{document.querySelector('#save-state').textContent='本机文件保存失败，浏览器保留副本';document.querySelector('#storage-warning').hidden=false;document.querySelector('#storage-warning').textContent='本机文件暂时未保存：'+err.message;throw err;});return queue;}
    async function init(){if(!/^https?:$/.test(location.protocol)){toast('请双击打开工作台.cmd，启动本机资料服务');return;}try{aiUI.init();const [catalog,stored,latest]=await Promise.all([api('/api/library'),api('/api/state'),api('/api/news').catch(()=>({items:[],sources:[],updatedAt:null}))]);L=catalog;news=latest;connected=true;applyCatalog();if(stored.state){const disk=M.restore(JSON.stringify(stored.state)),local=ctx.getState(),recovered=M.chooseRecovery(local,disk);ctx.setState(recovered);if(recovered===local){await persist(local);toast('已保留较新的浏览器记录并同步到本机文件');}}else await persist(ctx.getState());ctx.render();document.querySelector('#save-state').textContent='记录保存在本机文件，浏览器留副本';}catch(err){toast('本机资料暂时未连接，请启动本地服务：'+err.message);}}
    const distillUI=window.WBDistillUI(ctx,{getLibrary:()=>L,refsHTML,addTask,openTab:()=>{knowledgeTab='方法与案例';ctx.go('knowledge');}});
    const aiUI=window.WBAIUI(ctx);
    return {views:{home,projects,content,business,knowledge,radar,board,connections},handleClick,handleSubmit,handleInput,extendSearch,persist,init};
  };
})();
